CREATE TABLE IF NOT EXISTS system_metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS documents (
      slug TEXT PRIMARY KEY,
      doc_id TEXT UNIQUE,
      title TEXT,
      markdown TEXT NOT NULL,
      marks TEXT NOT NULL DEFAULT '{}',
      revision INTEGER NOT NULL DEFAULT 1,
      y_state_version BIGINT NOT NULL DEFAULT 0,
      share_state TEXT NOT NULL DEFAULT 'ACTIVE',
      access_epoch INTEGER NOT NULL DEFAULT 0,
      collab_bootstrap_epoch INTEGER NOT NULL DEFAULT 0,
      live_collab_seen_at TEXT,
      live_collab_access_epoch INTEGER,
      active INTEGER NOT NULL DEFAULT 1,
      owner_id TEXT,
      owner_secret TEXT,
      owner_secret_hash TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      y_state_blob BYTEA,
      deleted_at TEXT
    );

CREATE UNIQUE INDEX IF NOT EXISTS idx_documents_doc_id ON documents(doc_id);

CREATE INDEX IF NOT EXISTS idx_documents_share_state ON documents(share_state);

CREATE INDEX IF NOT EXISTS idx_documents_slug_revision ON documents(slug, revision);

CREATE INDEX IF NOT EXISTS idx_documents_owner_id ON documents(owner_id);

CREATE TABLE IF NOT EXISTS document_projections (
      document_slug TEXT PRIMARY KEY,
      revision INTEGER NOT NULL,
      y_state_version BIGINT NOT NULL DEFAULT 0,
      markdown TEXT NOT NULL,
      marks_json TEXT NOT NULL DEFAULT '{}',
      plain_text TEXT NOT NULL DEFAULT '',
      updated_at TEXT NOT NULL,
      health TEXT NOT NULL DEFAULT 'healthy',
      health_reason TEXT,
      FOREIGN KEY (document_slug) REFERENCES documents(slug)
    );

CREATE INDEX IF NOT EXISTS idx_document_projections_revision ON document_projections(document_slug, revision);

CREATE INDEX IF NOT EXISTS idx_document_projections_health ON document_projections(health, updated_at);

CREATE TABLE IF NOT EXISTS events (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      document_slug TEXT NOT NULL,
      event_type TEXT NOT NULL,
      event_data TEXT NOT NULL,
      actor TEXT NOT NULL,
      created_at TEXT NOT NULL,
      FOREIGN KEY (document_slug) REFERENCES documents(slug)
    );

CREATE TABLE IF NOT EXISTS document_access (
      token_id TEXT PRIMARY KEY,
      document_slug TEXT NOT NULL,
      role TEXT NOT NULL,
      secret_hash TEXT NOT NULL,
      created_at TEXT NOT NULL,
      revoked_at TEXT,
      FOREIGN KEY (document_slug) REFERENCES documents(slug)
    );

CREATE INDEX IF NOT EXISTS idx_document_access_slug ON document_access(document_slug);

CREATE INDEX IF NOT EXISTS idx_document_access_secret ON document_access(secret_hash);

CREATE TABLE IF NOT EXISTS document_events (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      document_slug TEXT NOT NULL,
      document_revision INTEGER,
      event_type TEXT NOT NULL,
      event_data TEXT NOT NULL,
      actor TEXT NOT NULL,
      idempotency_key TEXT,
      mutation_route TEXT,
      tombstone_revision INTEGER,
      created_at TEXT NOT NULL,
      acked_by TEXT,
      acked_at TEXT,
      FOREIGN KEY (document_slug) REFERENCES documents(slug)
    );

CREATE INDEX IF NOT EXISTS idx_document_events_slug_id ON document_events(document_slug, id);

CREATE INDEX IF NOT EXISTS idx_document_events_slug_tombstone ON document_events(document_slug, tombstone_revision, id);

CREATE INDEX IF NOT EXISTS idx_document_events_slug_revision ON document_events(document_slug, document_revision, id);

CREATE INDEX IF NOT EXISTS idx_document_events_slug_idempotency_route ON document_events(document_slug, idempotency_key, mutation_route, id);

CREATE TABLE IF NOT EXISTS server_incident_events (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      request_id TEXT,
      slug TEXT,
      subsystem TEXT NOT NULL,
      level TEXT NOT NULL,
      event_type TEXT NOT NULL,
      message TEXT NOT NULL,
      data_json TEXT NOT NULL,
      created_at TEXT NOT NULL
    );

CREATE INDEX IF NOT EXISTS idx_server_incident_events_request_id_created_at ON server_incident_events(request_id, created_at, id);

CREATE INDEX IF NOT EXISTS idx_server_incident_events_slug_created_at ON server_incident_events(slug, created_at, id);

CREATE INDEX IF NOT EXISTS idx_server_incident_events_subsystem_created_at ON server_incident_events(subsystem, created_at, id);

CREATE TABLE IF NOT EXISTS idempotency_keys (
      rowid BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,
      idempotency_key TEXT NOT NULL,
      document_slug TEXT NOT NULL,
      route TEXT NOT NULL,
      response_json TEXT NOT NULL,
      request_hash TEXT,
      created_at TEXT NOT NULL,
      PRIMARY KEY (idempotency_key, document_slug, route)
    );

CREATE TABLE IF NOT EXISTS mutation_idempotency (
      idempotency_key TEXT NOT NULL,
      document_slug TEXT NOT NULL,
      route TEXT NOT NULL,
      response_json TEXT NOT NULL,
      request_hash TEXT,
      status_code INTEGER NOT NULL DEFAULT 200,
      tombstone_revision INTEGER,
      state TEXT NOT NULL DEFAULT 'completed',
      completed_at TEXT,
      lease_expires_at TEXT,
      last_seen_at TEXT,
      reservation_token TEXT,
      created_at TEXT NOT NULL,
      PRIMARY KEY (idempotency_key, document_slug, route)
    );

CREATE INDEX IF NOT EXISTS idx_mutation_idempotency_slug_created_at
    ON mutation_idempotency(document_slug, created_at);

CREATE INDEX IF NOT EXISTS idx_mutation_idempotency_slug_tombstone
    ON mutation_idempotency(document_slug, tombstone_revision, created_at);

CREATE TABLE IF NOT EXISTS mutation_outbox (
      id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      document_slug TEXT NOT NULL,
      document_revision INTEGER,
      event_id BIGINT,
      event_type TEXT NOT NULL,
      event_data TEXT NOT NULL,
      actor TEXT NOT NULL,
      idempotency_key TEXT,
      mutation_route TEXT,
      tombstone_revision INTEGER,
      created_at TEXT NOT NULL,
      delivered_at TEXT
    );

CREATE INDEX IF NOT EXISTS idx_mutation_outbox_slug_id
    ON mutation_outbox(document_slug, id);

CREATE INDEX IF NOT EXISTS idx_mutation_outbox_slug_revision
    ON mutation_outbox(document_slug, document_revision, id);

CREATE INDEX IF NOT EXISTS idx_mutation_outbox_pending
    ON mutation_outbox(document_slug, delivered_at, tombstone_revision, id);

CREATE INDEX IF NOT EXISTS idx_mutation_outbox_slug_idempotency_route
    ON mutation_outbox(document_slug, idempotency_key, mutation_route, id);

CREATE UNIQUE INDEX IF NOT EXISTS idx_mutation_outbox_event_id_unique
    ON mutation_outbox(event_id)
    WHERE event_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS mark_tombstones (
      document_slug TEXT NOT NULL,
      mark_id TEXT NOT NULL,
      status TEXT NOT NULL,
      resolved_revision INTEGER NOT NULL,
      created_at TEXT NOT NULL,
      expires_at TEXT NOT NULL,
      PRIMARY KEY (document_slug, mark_id)
    );

CREATE INDEX IF NOT EXISTS idx_mark_tombstones_expires_at ON mark_tombstones(expires_at);

CREATE INDEX IF NOT EXISTS idx_mark_tombstones_slug_revision ON mark_tombstones(document_slug, resolved_revision);

CREATE TABLE IF NOT EXISTS document_blocks (
      document_id TEXT NOT NULL,
      block_id TEXT NOT NULL,
      ordinal INTEGER NOT NULL,
      node_type TEXT NOT NULL,
      attrs_json TEXT NOT NULL DEFAULT '{}',
      markdown_hash TEXT NOT NULL,
      text_preview TEXT NOT NULL DEFAULT '',
      created_revision INTEGER NOT NULL,
      last_seen_revision INTEGER NOT NULL,
      retired_revision INTEGER,
      PRIMARY KEY (document_id, block_id)
    );

CREATE UNIQUE INDEX IF NOT EXISTS idx_document_blocks_live_ordinal
    ON document_blocks(document_id, ordinal)
    WHERE retired_revision IS NULL;

CREATE INDEX IF NOT EXISTS idx_document_blocks_live_doc
    ON document_blocks(document_id, retired_revision, ordinal);

CREATE TABLE IF NOT EXISTS document_y_updates (
      seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      document_slug TEXT NOT NULL,
      update_blob BYTEA NOT NULL,
      source_actor TEXT,
      created_at TEXT NOT NULL,
      FOREIGN KEY (document_slug) REFERENCES documents(slug)
    );

CREATE INDEX IF NOT EXISTS idx_document_y_updates_slug_seq ON document_y_updates(document_slug, seq);

CREATE INDEX IF NOT EXISTS idx_document_y_updates_slug_created_at ON document_y_updates(document_slug, created_at);

CREATE TABLE IF NOT EXISTS document_y_snapshots (
      document_slug TEXT NOT NULL,
      version BIGINT NOT NULL,
      snapshot_blob BYTEA NOT NULL,
      created_at TEXT NOT NULL,
      PRIMARY KEY (document_slug, version),
      FOREIGN KEY (document_slug) REFERENCES documents(slug)
    );

CREATE INDEX IF NOT EXISTS idx_document_y_snapshots_slug_version ON document_y_snapshots(document_slug, version);

CREATE TABLE IF NOT EXISTS maintenance_runs (
      run_key TEXT PRIMARY KEY,
      completed_at TEXT NOT NULL,
      summary TEXT
    );

CREATE TABLE IF NOT EXISTS share_auth_sessions (
      session_token_hash TEXT PRIMARY KEY,
      provider TEXT NOT NULL,
      every_user_id INTEGER NOT NULL,
      email TEXT NOT NULL,
      name TEXT,
      subscriber INTEGER NOT NULL DEFAULT 1,
      access_token TEXT NOT NULL,
      refresh_token TEXT,
      access_expires_at TEXT NOT NULL,
      session_expires_at TEXT NOT NULL,
      last_verified_at TEXT NOT NULL,
      revoked_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );

CREATE INDEX IF NOT EXISTS idx_share_auth_sessions_revoked ON share_auth_sessions(revoked_at);

CREATE INDEX IF NOT EXISTS idx_share_auth_sessions_expiry ON share_auth_sessions(session_expires_at);

CREATE TABLE IF NOT EXISTS active_collab_connections (
      connection_id TEXT PRIMARY KEY,
      document_slug TEXT NOT NULL,
      role TEXT NOT NULL,
      access_epoch INTEGER NOT NULL,
      instance_id TEXT NOT NULL,
      connected_at TEXT NOT NULL,
      last_seen_at TEXT NOT NULL
    );

CREATE INDEX IF NOT EXISTS idx_active_collab_connections_slug_seen
    ON active_collab_connections(document_slug, last_seen_at);

CREATE INDEX IF NOT EXISTS idx_active_collab_connections_instance_seen
    ON active_collab_connections(instance_id, last_seen_at);

CREATE TABLE IF NOT EXISTS user_document_visits (
      every_user_id INTEGER NOT NULL,
      document_slug TEXT NOT NULL,
      role TEXT,
      first_visited_at TEXT NOT NULL,
      last_visited_at TEXT NOT NULL,
      PRIMARY KEY (every_user_id, document_slug)
    );

CREATE INDEX IF NOT EXISTS idx_udv_user_last ON user_document_visits(every_user_id, last_visited_at);

CREATE INDEX IF NOT EXISTS idx_udv_document_slug ON user_document_visits(document_slug);

CREATE TABLE IF NOT EXISTS library_documents (
      every_user_id INTEGER PRIMARY KEY,
      document_slug TEXT NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      FOREIGN KEY (document_slug) REFERENCES documents(slug)
    );

CREATE UNIQUE INDEX IF NOT EXISTS idx_library_documents_slug ON library_documents(document_slug);

CREATE TABLE IF NOT EXISTS document_html_snapshots (
  document_slug TEXT PRIMARY KEY REFERENCES documents(slug) ON DELETE CASCADE,
  revision INTEGER NOT NULL,
  document_updated_at TEXT NOT NULL,
  html TEXT NOT NULL
);
